ALTER TABLE public.profiles ADD COLUMN country text;
CREATE OR REPLACE FUNCTION public.handle_new_curator() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE handle text; country_code text; BEGIN country_code=upper(coalesce(NEW.raw_user_meta_data->>'country','')); IF country_code !~ '^[A-Z]{2}$' THEN RAISE EXCEPTION 'Country is required'; END IF; handle=lower(regexp_replace(coalesce(NEW.raw_user_meta_data->>'username','curator'),'[^a-zA-Z0-9_-]','','g')); IF length(handle)=0 THEN handle='curator'; END IF; IF EXISTS(SELECT 1 FROM public.profiles WHERE username=handle) THEN handle=handle||'-'||substr(NEW.id::text,1,8); END IF; INSERT INTO public.profiles(id,user_id,name,username,country) VALUES(NEW.id::text,NEW.id,coalesce(nullif(NEW.raw_user_meta_data->>'name',''),'Curator'),handle,country_code); RETURN NEW; END $$;
REVOKE UPDATE ON public.profiles FROM authenticated;
GRANT UPDATE(name,bio,avatar,location,country) ON public.profiles TO authenticated;
CREATE TABLE public.plan_interests (user_id uuid PRIMARY KEY REFERENCES public.profiles(user_id) ON DELETE CASCADE, plan text NOT NULL CHECK (plan IN ('free','pro','studio')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.plan_interests TO authenticated; GRANT ALL ON public.plan_interests TO service_role;
ALTER TABLE public.plan_interests ENABLE ROW LEVEL SECURITY;
CREATE POLICY plan_interests_own ON public.plan_interests FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TRIGGER plan_interests_updated BEFORE UPDATE ON public.plan_interests FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TABLE public.subscriptions (user_id uuid PRIMARY KEY REFERENCES public.profiles(user_id) ON DELETE CASCADE, plan text NOT NULL DEFAULT 'free' CHECK(plan IN ('free','pro','studio')), status text NOT NULL DEFAULT 'inactive' CHECK(status IN ('inactive','trialing','active','past_due','canceled')), currency text NOT NULL DEFAULT 'eur', monthly_amount_minor integer NOT NULL DEFAULT 0 CHECK(monthly_amount_minor>=0), stripe_customer_id text UNIQUE, stripe_subscription_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscriptions_read ON public.subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TRIGGER subscriptions_updated BEFORE UPDATE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TABLE public.app_errors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(user_id) ON DELETE SET NULL, category text NOT NULL, path text NOT NULL, fingerprint text NOT NULL, resolved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.app_errors TO authenticated; GRANT ALL ON public.app_errors TO service_role;
ALTER TABLE public.app_errors ENABLE ROW LEVEL SECURITY;
CREATE POLICY app_errors_admin_read ON public.app_errors FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY app_errors_admin_update ON public.app_errors FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TRIGGER app_errors_updated BEFORE UPDATE ON public.app_errors FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE INDEX app_errors_created ON public.app_errors(created_at DESC); CREATE INDEX app_errors_user_created ON public.app_errors(user_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.report_app_error(error_category text,error_path text,error_fingerprint text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF error_category NOT IN ('runtime','unhandled_rejection','operation','route') OR error_path !~ '^/[a-zA-Z0-9/_.$-]{0,200}$' OR error_fingerprint !~ '^[a-f0-9]{8,64}$' THEN RAISE EXCEPTION 'Invalid diagnostic'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); IF (SELECT count(*) FROM public.app_errors WHERE user_id=auth.uid() AND created_at>now()-interval '1 hour')>=20 THEN RETURN false; END IF; IF EXISTS(SELECT 1 FROM public.app_errors WHERE user_id=auth.uid() AND fingerprint=error_fingerprint AND created_at>now()-interval '5 minutes') THEN RETURN false; END IF; INSERT INTO public.app_errors(user_id,category,path,fingerprint) VALUES(auth.uid(),error_category,error_path,error_fingerprint); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.report_app_error(text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.report_app_error(text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_platform_metrics() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT jsonb_build_object('accounts',(SELECT count(*) FROM public.profiles WHERE user_id IS NOT NULL),'new_accounts_30d',(SELECT count(*) FROM public.profiles WHERE user_id IS NOT NULL AND created_at>now()-interval '30 days'),'museums',(SELECT count(*) FROM public.museums),'public_museums',(SELECT count(*) FROM public.museums WHERE is_public),'objects',(SELECT count(*) FROM public.objects),'open_errors',(SELECT count(*) FROM public.app_errors WHERE NOT resolved),'errors_7d',(SELECT count(*) FROM public.app_errors WHERE created_at>now()-interval '7 days'),'open_tasks',(SELECT count(*) FROM public.dev_tasks WHERE payload->>'status'<>'done'),'plan_interests',(SELECT coalesce(jsonb_object_agg(plan,n),'{}'::jsonb) FROM (SELECT plan,count(*) n FROM public.plan_interests GROUP BY plan) s),'active_subscriptions',(SELECT count(*) FROM public.subscriptions WHERE status='active' AND plan<>'free'),'mrr_by_currency',(SELECT coalesce(jsonb_object_agg(currency,amount),'{}'::jsonb) FROM (SELECT currency,sum(monthly_amount_minor) amount FROM public.subscriptions WHERE status='active' AND plan<>'free' GROUP BY currency) s),'countries',(SELECT coalesce(jsonb_object_agg(country,n),'{}'::jsonb) FROM (SELECT country,count(*) n FROM public.profiles WHERE user_id IS NOT NULL AND country IS NOT NULL GROUP BY country) s)) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.admin_platform_metrics() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_platform_metrics() TO authenticated;